SELECT percentile_cont(0.75) within GROUP (ORDER BY icustays.los) AS percentile_75 FROM icustays JOIN admissions ON icustays.subject_id = admissions.subject_id JOIN patients ON admissions.subject_id = patients.subject_id WHERE admissions.admission_type_id = 170372003 AND patients.gender = 1 AND patients.anchor_age >= 70 AND EXISTS (SELECT 1 FROM diagnoses_icd WHERE diagnoses_icd.subject_id = admissions.subject_id AND diagnoses_icd.icd_code = '170372003');